## よくあるバグパターンと修正

### 1. 時刻比較の間違い

**バグのあるコード:**
```javascript
// 間違った比較（現在時刻 > 有効期限で判定）
function validateToken(token) {
    const decoded = jwt.verify(token, SECRET_KEY);
    const currentTime = Date.now() / 1000;

    // バグ: 不等号が逆
    if (currentTime > decoded.exp) {
        return { valid: true, user: decoded };
    }

    throw new Error('Token expired');
}
```

**修正版:**
```javascript
function validateToken(token) {
    const decoded = jwt.verify(token, SECRET_KEY);
    const currentTime = Math.floor(Date.now() / 1000);

    // 修正: 現在時刻が有効期限を過ぎていたら無効
    if (currentTime >= decoded.exp) {
        throw new Error('Token expired');
    }

    return { valid: true, user: decoded };
}
```

### 2. 時刻の単位統一

**バグのあるコード:**
```javascript
function createToken(userId) {
    const payload = {
        userId: userId,
        // バグ: ミリ秒とUNIXタイムスタンプの混在
        exp: Date.now() + (60 * 60 * 1000) // ミリ秒
    };

    return jwt.sign(payload, SECRET_KEY);
}

function validateToken(token) {
    const decoded = jwt.verify(token, SECRET_KEY);
    const currentTime = Math.floor(Date.now() / 1000); // 秒

    if (currentTime >= decoded.exp) { // 単位が違う
        throw new Error('Token expired');
    }

    return { valid: true, user: decoded };
}
```

**修正版:**
```javascript
function createToken(userId) {
    const payload = {
        userId: userId,
        iat: Math.floor(Date.now() / 1000),
        // 修正: 秒単位で統一
        exp: Math.floor(Date.now() / 1000) + (60 * 60) // 1時間後
    };

    return jwt.sign(payload, SECRET_KEY);
}

function validateToken(token) {
    const decoded = jwt.verify(token, SECRET_KEY);
    const currentTime = Math.floor(Date.now() / 1000);

    if (currentTime >= decoded.exp) {
        throw new Error('Token expired');
    }

    return { valid: true, user: decoded };
}
```

### 3. Express.js ミドルウェアの完全な修正版

```javascript
const jwt = require('jsonwebtoken');

function authMiddleware(req, res, next) {
    try {
        // Authorizationヘッダーの取得
        const authHeader = req.headers.authorization;

        if (!authHeader || !authHeader.startsWith('Bearer ')) {
            return res.status(401).json({ 
                error: 'Authorization header missing or invalid format' 
            });
        }

        const token = authHeader.substring(7); // "Bearer " を除去

        if (!token) {
            return res.status(401).json({ error: 'Token not provided' });
        }

        // トークンの検証と有効期限チェック
        const decoded = jwt.verify(token, process.env.JWT_SECRET);
        const currentTime = Math.floor(Date.now() / 1000);

        // 有効期限チェック（jwt.verifyが自動でチェックするが、明示的にも行う）
        if (decoded.exp && currentTime >= decoded.exp) {
            return res.status(401).json({ error: 'Token has expired' });
        }

        // 発行時刻チェック（未来のトークンを防ぐ）
        if (decoded.iat && decoded.iat > currentTime + 60) { // 1分の許容誤差
            return res.status(401).json({ error: 'Token issued in the future' });
        }

        // ユーザー情報をリクエストに追加
        req.user = {
            userId: decoded.userId,
            email: decoded.email,
            // その他必要な情報
        };

        next();

    } catch (error) {
        if (error.name === 'JsonWebTokenError') {
            return res.status(401).json({ error: 'Invalid token' });
        }

        if (error.name === 'TokenExpiredError') {
            return res.status(401).json({ error: 'Token has expired' });
        }

        console.error('Authentication error:', error);
        return res.status(500).json({ error: 'Internal server error' });
    }
}

module.exports = authMiddleware;
```

### 4. より堅牢なバージョン（TypeScript）

```typescript
import { Request, Response, NextFunction } from 'express';
import jwt from 'jsonwebtoken';

interface TokenPayload {
    userId: string;
    email: string;
    iat: number;
    exp: number;
}

interface AuthRequest extends Request {
    user?: {
        userId: string;
        email: string;
    };
}

export function authMiddleware(
    req: AuthRequest, 
    res: Response, 
    next: NextFunction
): void {
    try {
        const authHeader = req.headers.authorization;

        if (!authHeader?.startsWith('Bearer ')) {
            res.status(401).json({ 
                error: 'Authorization header missing or invalid format' 
            });
            return;
        }

        const token = authHeader.substring(7);

        if (!token.trim()) {
            res.status(401).json({ error: 'Token not provided' });
            return;
        }

        const secret = process.env.JWT_SECRET;
        if (!secret) {
            console.error('JWT_SECRET not configured');
            res.status(500).json({ error: 'Server configuration error' });
            return;
        }

        // トークンの検証
        const decoded = jwt.verify(token, secret) as TokenPayload;
        const currentTime = Math.floor(Date.now() / 1000);

        // 追加の有効期限チェック
        if (currentTime >= decoded.exp) {
            res.status(401).json({ error: 'Token has expired' });
            return;
        }

        // 発行時刻チェック（クロックスキュー対策）
        const maxClockSkew = 300; // 5分の許容誤差
        if (decoded.iat > currentTime + maxClockSkew) {
            res.status(401).json({ error: 'Token issued in the future' });
            return;
        }

        req.user = {
            userId: decoded.userId,
            email: decoded.email
        };

        next();

    } catch (error) {
        if (error instanceof jwt.JsonWebTokenError) {
            res.status(401).json({ error: 'Invalid token' });
            return;
        }

        if (error instanceof jwt.TokenExpiredError) {
            res.status(401).json({ error: 'Token has expired' });
            return;
        }

        console.error('Authentication error:', error);
        res.status(500).json({ error: 'Internal server error' });
    }
}
```

## 主な修正ポイント

1. **時刻単位の統一**: ミリ秒と秒の混在を避ける
2. **比較演算子の修正**: 有効期限との正しい比較
3. **エラーハンドリングの改善**: 適切な例外処理
4. **セキュリティ強化**: 未来のトークンチェック、クロックスキュー対策
5. **型安全性**: TypeScriptでの型定義

