### 3. より堅牢な実装
```javascript
const authMiddleware = (options = {}) => {
    const { 
        gracePeriod = 0, // 有効期限の猶予時間（秒）
        refreshThreshold = 300 // リフレッシュ推奨時間（秒）
    } = options;

    return async (req, res, next) => {
        try {
            const token = extractToken(req);

            if (!token) {
                return res.status(401).json({ error: 'Token required' });
            }

            const decoded = jwt.verify(token, process.env.JWT_SECRET);
            const now = Math.floor(Date.now() / 1000);

            // 有効期限チェック（猶予時間考慮）
            if (decoded.exp && decoded.exp + gracePeriod < now) {
                return res.status(401).json({ 
                    error: 'Token expired',
                    code: 'TOKEN_EXPIRED'
                });
            }

            // リフレッシュ推奨の警告
            if (decoded.exp && decoded.exp - now < refreshThreshold) {
                res.set('X-Token-Refresh-Suggested', 'true');
            }

            req.user = decoded;
            next();

        } catch (error) {
            handleAuthError(error, res);
        }
    };
};

function extractToken(req) {
    const authHeader = req.headers.authorization;
    if (authHeader && authHeader.startsWith('Bearer ')) {
        return authHeader.substring(7);
    }
    return null;
}

function handleAuthError(error, res) {
    const errorMap = {
        'TokenExpiredError': { status: 401, message: 'Token expired' },
        'JsonWebTokenError': { status: 401, message: 'Invalid token' },
        'NotBeforeError': { status: 401, message: 'Token not active' }
    };

    const errorInfo = errorMap[error.name] || { 
        status: 500, 
        message: 'Authentication error' 
    };

    return res.status(errorInfo.status).json({ error: errorInfo.message });
}
```

主な修正点：
- 時刻単位の統一（秒 vs ミリ秒）
- `jwt.verify()`の活用（自動的に有効期限をチェック）
- 適切なエラーハンドリング
- トークン抽出の改善
- 猶予時間やリフレッシュ推奨機能の追加

