normal_texts:
Node.jsでPostgreSQLのコネクションプーリングをセットアップする方法を、段階的に説明いたします。

## 1. 必要なパッケージのインストール

```bash
npm install pg
npm install --save-dev @types/pg  # TypeScriptを使用する場合
```

## 2. 基本的なコネクションプールの設定

```javascript
const { Pool } = require('pg');

// プールの設定
const pool = new Pool({
  user: 'your_username',
  host: 'localhost',
  database: 'your_database',
  password: 'your_password',
  port: 5432,

  // プール設定
  max: 20,        // プール内の最大コネクション数
  min: 4,         // プール内の最小コネクション数
  idle: 1000,     // アイドル状態のコネクションを維持する時間（ミリ秒）
  acquire: 60000, // プールからコネクションを取得するまでの最大待機時間
});

module.exports = pool;
```

## 3. 環境変数を使用した設定

```javascript
// .env ファイル
/*
DB_USER=your_username
DB_HOST=localhost
DB_DATABASE=your_database
DB_PASSWORD=your_password
DB_PORT=5432
*/

require('dotenv').config();
const { Pool } = require('pg');

const pool = new Pool({
  user: process.env.DB_USER,
  host: process.env.DB_HOST,
  database: process.env.DB_DATABASE,
  password: process.env.DB_PASSWORD,
  port: process.env.DB_PORT,
  max: 20,
  min: 4,
  idle: 10000,
  acquire: 60000,
});
```

## 4. プールを使用したクエリの実行

```javascript
// database.js
const pool = require('./pool-config');

// 単純なクエリ
async function getAllUsers() {
  try {
    const result = await pool.query('SELECT * FROM users');
    return result.rows;
  } catch (error) {
    console.error('Database query error:', error);
    throw error;
  }
}

// パラメータ付きクエリ
async function getUserById(id) {
  try {
    const result = await pool.query('SELECT * FROM users WHERE id = $1', [id]);
    return result.rows[0];
  } catch (error) {
    console.error('Database query error:', error);
    throw error;
  }
}

// 個別のクライアントを使用する場合（トランザクション等）
async function transferMoney(fromUserId, toUserId, amount) {
  const client = await pool.connect();
  try {
    await client.query('BEGIN');

    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE user_id = $2',
      [amount, fromUserId]
    );

    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE user_id = $2',
      [amount, toUserId]
    );

    await client.query('COMMIT');
    console.log('Transaction completed successfully');
  } catch (error) {
    await client.query('ROLLBACK');
    console.error('Transaction failed:', error);
    throw error;
  } finally {
    client.release(); // 重要：必ずクライアントを解放
  }
}
```

## 5. Express.jsでの使用例

```javascript
const express = require('express');
const pool = require('./database/pool-config');

const app = express();
app.use(express.json());

// ユーザー一覧を取得
app.get('/users', async (req, res) => {
  try {
    const result = await pool.query('SELECT id, name, email FROM users');
    res.json(result.rows);
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// 新しいユーザーを作成
app.post('/users', async (req, res) => {
  const { name, email } = req.body;

  try {
    const result = await pool.query(
      'INSERT INTO users (name, email) VALUES ($1, $2) RETURNING *',
      [name, email]
    );
    res.status(201).json(result.rows[0]);
  } catch (error) {
    console.error('Error creating user:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

## 6. エラーハンドリングとログ

```javascript
const { Pool } = require('pg');

const pool = new Pool({
  // 設定は上記と同様
});

// プールイベントのリスニング
pool.on('connect', (client) => {
  console.log('New client connected to the database');
});

pool.on('error', (err, client) => {
  console.error('Unexpected error on idle client', err);
  process.exit(-1);
});

pool.on('remove', (client) => {
  console.log('Client removed from pool');
});

// グレースフルシャットダウン
process.on('SIGINT', async () => {
  console.log('Shutting down gracefully...');
  await pool.end();
  process.exit(0);
});
```

## 7. TypeScriptでの実装

```typescript
import { Pool, PoolClient, QueryResult } from 'pg';

interface DatabaseConfig {
  user: string;
  host: string;
  database: string;
  password: string;
  port: number;
}

class Database {
  private pool: Pool;

  constructor(config: DatabaseConfig) {
    this.pool = new Pool({
      ...config,
      max: 20,
      min: 4,
      idle: 10000,
      acquire: 60000,
    });
  }

  async query(text: string, params?: any[]): Promise<QueryResult> {
    try {
      return await this.pool.query(text, params);
    } catch (error) {
      console.error('Database query error:', error);
      throw error;
    }
  }

  async getClient(): Promise<PoolClient> {
    return await this.pool.connect();
  }

  async close(): Promise<void> {
    await this.pool.end();
  }
}

export default Database;
```

## ベストプラクティス

1. **適切なプールサイズの設定**: アプリケーションの負荷に応じて調整
2. **必ずクライアントを解放**: `client.release()` を忘れずに
3. **エラーハンドリング**: 適切なエラー処理とログ出力
4. **環境変数の使用**: 機密情報は環境変数で管理
5. **グレースフルシャットダウン**: アプリケーション終了時にプールを適切に閉じる

このセットアップにより、効率的で安全なPostgreSQLコネクションプーリングが実現できます。

Node.jsでPostgreSQLのコネクションプーリングをセットアップする方法について、詳しく説明します。

## 必要なパッケージのインストール

```bash
npm install pg
# TypeScriptを使用する場合
npm install @types/pg --save-dev
```

## 基本的なコネクションプール設定

### 1. 基本設定（JavaScript）

```javascript
const { Pool } = require('pg');

const pool = new Pool({
  user: 'your_username',
  host: 'localhost',
  database: 'your_database',
  password: 'your_password',
  port: 5432,

  // プール設定
  max: 20,                    // 最大コネクション数
  idleTimeoutMillis: 30000,   // アイドルタイムアウト（30秒）
  connectionTimeoutMillis: 2000, // 接続タイムアウト（2秒）
});

module.exports = pool;
```

### 2. 環境変数を使用した設定

```javascript
const { Pool } = require('pg');

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  // または
  user: process.env.DB_USER,
  host: process.env.DB_HOST,
  database: process.env.DB_NAME,
  password: process.env.DB_PASSWORD,
  port: process.env.DB_PORT || 5432,

  max: parseInt(process.env.DB_POOL_SIZE || '20'),
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000,
});

module.exports = pool;
```

### 3. TypeScript版

```typescript
import { Pool, PoolConfig } from 'pg';

const config: PoolConfig = {
  user: process.env.DB_USER,
  host: process.env.DB_HOST,
  database: process.env.DB_NAME,
  password: process.env.DB_PASSWORD,
  port: parseInt(process.env.DB_PORT || '5432'),

  max: 20,
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000,
};

const pool = new Pool(config);

export default pool;
```

## 実際の使用例

### 1. 基本的なクエリ実行

```javascript
const pool = require('./db-config');

async function getUserById(id) {
  const client = await pool.connect();
  try {
    const result = await client.query('SELECT * FROM users WHERE id = $1', [id]);
    return result.rows[0];
  } finally {
    client.release(); // 重要：必ずコネクションを解放
  }
}

// より簡潔な書き方（推奨）
async function getUserByIdSimple(id) {
  const result = await pool.query('SELECT * FROM users WHERE id = $1', [id]);
  return result.rows[0];
}
```

### 2. トランザクションの使用

```javascript
async function transferMoney(fromUserId, toUserId, amount) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');

    // 送金元の残高を減らす
    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE user_id = $2',
      [amount, fromUserId]
    );

    // 送金先の残高を増やす
    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE user_id = $2',
      [amount, toUserId]
    );

    await client.query('COMMIT');
    return { success: true };

  } catch (error) {
    await client.query('ROLLBACK');
    throw error;
  } finally {
    client.release();
  }
}
```

### 3. エラーハンドリングとログ出力

```javascript
const pool = require('./db-config');

// プールイベントの監視
pool.on('connect', (client) => {
  console.log('新しいクライアントが接続されました');
});

pool.on('error', (err, client) => {
  console.error('データベースプールでエラーが発生しました:', err);
});

// グレースフルシャットダウン
process.on('SIGINT', async () => {
  console.log('アプリケーションを終了しています...');
  await pool.end();
  process.exit(0);
});
```

## 完全な実装例（Express.js + TypeScript）

```typescript
// db/pool.ts
import { Pool } from 'pg';

export const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000,
});

// db/users.ts
import { pool } from './pool';

export interface User {
  id: number;
  name: string;
  email: string;
}

export class UserService {
  async getAllUsers(): Promise<User[]> {
    const result = await pool.query('SELECT * FROM users ORDER BY id');
    return result.rows;
  }

  async createUser(name: string, email: string): Promise<User> {
    const result = await pool.query(
      'INSERT INTO users (name, email) VALUES ($1, $2) RETURNING *',
      [name, email]
    );
    return result.rows[0];
  }

  async updateUser(id: number, name: string, email: string): Promise<User | null> {
    const result = await pool.query(
      'UPDATE users SET name = $1, email = $2 WHERE id = $3 RETURNING *',
      [name, email, id]
    );
    return result.rows[0] || null;
  }

  async deleteUser(id: number): Promise<boolean> {
    const result = await pool.query('DELETE FROM users WHERE id = $1', [id]);
    return result.rowCount > 0;
  }
}

// app.ts
import express from 'express';
import { UserService } from './db/users';
import { pool } from './db/pool';

const app = express();
const userService = new UserService();

app.use(express.json());

app.get('/users', async (req, res) => {
  try {
    const users = await userService.getAllUsers();
    res.json(users);
  } catch (error) {
    console.error('Error fetching users:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

app.post('/users', async (req, res) => {
  try {
    const { name, email } = req.body;
    const user = await userService.createUser(name, email);
    res.status(201).json(user);
  } catch (error) {
    console.error('Error creating user:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// グレースフルシャットダウン
process.on('SIGINT', async () => {
  console.log('Shutting down gracefully...');
  await pool.end();
  process.exit(0);
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});
```

## 設定パラメータの説明

- **max**: プール内の最大コネクション数
- **min**: プール内の最小コネクション数（デフォルト: 0）
- **idleTimeoutMillis**: アイドル状態のコネクションが閉じられるまでの時間
- **connectionTimeoutMillis**: 新しいコネクションの取得を待つ最大時間
- **statement_timeout**: SQLステートメントのタイムアウト
- **query_timeout**: クエリのタイムアウト

このようにコネクションプーリングを適切に設定することで、パフォーマンスとリソース効率を向上させることができます。

Node.jsでPostgreSQLのコネクションプーリングをセットアップする方法を詳しく説明します。

## 1. 必要なパッケージのインストール

```bash
npm install pg
# TypeScriptを使用する場合
npm install @types/pg --save-dev
```

## 2. 基本的なコネクションプールの設定

```javascript
const { Pool } = require('pg');

// コネクションプールの設定
const pool = new Pool({
  user: 'your_username',
  host: 'localhost',
  database: 'your_database',
  password: 'your_password',
  port: 5432,

  // プール設定
  max: 20,          // 最大コネクション数
  min: 5,           // 最小コネクション数
  idleTimeoutMillis: 30000, // アイドル接続のタイムアウト（30秒）
  connectionTimeoutMillis: 2000, // 接続タイムアウト（2秒）
});
```

## 3. 環境変数を使用した設定

```javascript
require('dotenv').config();

const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  // または個別に設定
  user: process.env.DB_USER,
  host: process.env.DB_HOST,
  database: process.env.DB_NAME,
  password: process.env.DB_PASSWORD,
  port: process.env.DB_PORT,

  max: parseInt(process.env.DB_POOL_MAX) || 20,
  min: parseInt(process.env.DB_POOL_MIN) || 5,
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000,
});
```

## 4. データベース操作の実装

```javascript
// 基本的なクエリ実行
async function executeQuery(text, params) {
  const client = await pool.connect();
  try {
    const result = await client.query(text, params);
    return result;
  } catch (error) {
    throw error;
  } finally {
    client.release(); // 重要：コネクションをプールに戻す
  }
}

// より簡潔な方法（推奨）
async function simpleQuery(text, params) {
  try {
    const result = await pool.query(text, params);
    return result;
  } catch (error) {
    throw error;
  }
}
```

## 5. 実用的な例

```javascript
const express = require('express');
const { Pool } = require('pg');

const app = express();
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000,
  connectionTimeoutMillis: 2000,
});

// ユーザー取得API
app.get('/users/:id', async (req, res) => {
  try {
    const { id } = req.params;
    const result = await pool.query('SELECT * FROM users WHERE id = $1', [id]);

    if (result.rows.length === 0) {
      return res.status(404).json({ message: 'User not found' });
    }

    res.json(result.rows[0]);
  } catch (error) {
    console.error('Database error:', error);
    res.status(500).json({ message: 'Internal server error' });
  }
});

// ユーザー作成API
app.post('/users', async (req, res) => {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');

    const { name, email } = req.body;
    const userResult = await client.query(
      'INSERT INTO users (name, email) VALUES ($1, $2) RETURNING *',
      [name, email]
    );

    // 関連データも挿入する例
    await client.query(
      'INSERT INTO user_profiles (user_id, created_at) VALUES ($1, NOW())',
      [userResult.rows[0].id]
    );

    await client.query('COMMIT');
    res.status(201).json(userResult.rows[0]);

  } catch (error) {
    await client.query('ROLLBACK');
    console.error('Transaction error:', error);
    res.status(500).json({ message: 'Failed to create user' });
  } finally {
    client.release();
  }
});
```

## 6. コネクションプールのモニタリング

```javascript
// プールの状態を監視
function logPoolStats() {
  console.log('Pool stats:', {
    totalCount: pool.totalCount,      // 総コネクション数
    idleCount: pool.idleCount,        // アイドル中のコネクション数
    waitingCount: pool.waitingCount   // 待機中のリクエスト数
  });
}

// 定期的にログ出力
setInterval(logPoolStats, 10000);

// プールイベントの監視
pool.on('connect', (client) => {
  console.log('New client connected');
});

pool.on('remove', (client) => {
  console.log('Client removed from pool');
});

pool.on('error', (err) => {
  console.error('Pool error:', err);
});
```

## 7. アプリケーション終了時のクリーンアップ

```javascript
// Graceful shutdown
process.on('SIGINT', async () => {
  console.log('Shutting down gracefully...');

  try {
    await pool.end();
    console.log('Database pool closed');
    process.exit(0);
  } catch (error) {
    console.error('Error during shutdown:', error);
    process.exit(1);
  }
});
```

## 8. TypeScript版の実装

```typescript
import { Pool, PoolConfig, QueryResult } from 'pg';

interface DatabaseConfig extends PoolConfig {
  max?: number;
  min?: number;
  idleTimeoutMillis?: number;
  connectionTimeoutMillis?: number;
}

class Database {
  private pool: Pool;

  constructor(config: DatabaseConfig) {
    this.pool = new Pool(config);
  }

  async query<T = any>(text: string, params?: any[]): Promise<QueryResult<T>> {
    return await this.pool.query(text, params);
  }

  async transaction<T>(callback: (client: any) => Promise<T>): Promise<T> {
    const client = await this.pool.connect();

    try {
      await client.query('BEGIN');
      const result = await callback(client);
      await client.query('COMMIT');
      return result;
    } catch (error) {
      await client.query('ROLLBACK');
      throw error;
    } finally {
      client.release();
    }
  }

  async close(): Promise<void> {
    await this.pool.end();
  }
}

// 使用例
const db = new Database({
  connectionString: process.env.DATABASE_URL,
  max: 20,
  idleTimeoutMillis: 30000,
});

export default db;
```

## 推奨事項

1. **適切なプールサイズ**: 通常は10-20コネクションで十分
2. **エラーハンドリング**: 必ずtry-catchでエラーを処理
3. **コネクション解放**: client.release()を忘れずに呼び出す
4. **環境変数**: 接続情報は環境変数で管理
5. **監視**: プールの状態を定期的に監視

