  try {
    const client = await pool.connect();
    try {
      const result = await client.query('SELECT * FROM users');
      return result.rows;
    } finally {
      client.release(); // 必ずrelease()を呼ぶ
    }
  } catch (err) {
    console.error('データベースエラー:', err);
    throw err;
  }
