  pool.end();
});
```

## 環境変数使う版

```javascript
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  // または
  user: process.env.DB_USER,
  password: process.env.DB_PASS,
  host: process.env.DB_HOST,
  port: process.env.DB_PORT,
  database: process.env.DB_NAME,
  max: parseInt(process.env.DB_POOL_SIZE) || 10,
});
```

## プール設定詳細

```javascript
const pool = new Pool({
  max: 20,                    // 最大接続数（デフォルト10）
  min: 5,                     // 最小接続数（デフォルト0） 
  acquireTimeoutMillis: 0,    // 接続取得タイムアウト（0=無制限）
  createTimeoutMillis: 30000, // 新接続作成タイムアウト
  destroyTimeoutMillis: 5000, // 接続破棄タイムアウト
  idleTimeoutMillis: 30000,   // アイドル接続タイムアウト
  reapIntervalMillis: 1000,   // クリーンアップ間隔
  createRetryIntervalMillis: 200, // 接続リトライ間隔
});
```

## エラーハンドリング

```javascript
pool.on('error', (err, client) => {
  console.error('プール内クライアントエラー:', err);
});

pool.on('connect', (client) => {
  console.log('新接続確立');
});

pool.on('remove', (client) => {
  console.log('接続削除');
});
```

## 使用パターン

**直接クエリ（推奨）:**
```javascript
const result = await pool.query('SELECT * FROM users');
```

**手動接続管理:**
```javascript
const client = await pool.connect();
try {
  await client.query('BEGIN');
  const result = await client.query('INSERT INTO users...');
  await client.query('COMMIT');
} catch (err) {
  await client.query('ROLLBACK');
  throw err;
} finally {
  client.release(); // 必須！
}
```

プール = 接続再利用。新接続コスト削減。負荷高いアプリ必須。

