  min: 5,         // 最小接続数  
  idle: 30000,    // アイドル時間(ms)
  acquire: 60000, // 接続取得タイムアウト
})
```

クエリ実行:
```js
// 自動 接続返却
const result = await pool.query('SELECT * FROM users')

// 手動 接続管理
const client = await pool.connect()
try {
  const result = await client.query('SELECT * FROM users')
} finally {
  client.release()
}
```

プール利点:
- 接続再利用 → ハンドシェイク省略
- 高負荷時 安定性
- メモリ効率

設定のコツ:
- `max` = CPU コア数 × 2-4
- `idle` = 30秒程度
- アプリ終了時 `pool.end()`

コネクションプール = DB接続 再利用。毎回接続作成 不要 → 高速化。

## pg-pool使用

```bash
npm install pg
```

```javascript
const { Pool } = require('pg');

// プール設定
const pool = new Pool({
  user: 'username',
  host: 'localhost',
  database: 'mydb',
  password: 'password',
  port: 5432,
  max: 20,        // 最大接続数
  min: 5,         // 最小接続数
  idle: 10000,    // アイドル時間(ms)
  acquire: 60000, // 取得タイムアウト(ms)
});

// クエリ実行
async function getUser(id) {
  const client = await pool.connect();
  try {
    const result = await client.query('SELECT * FROM users WHERE id = $1', [id]);
    return result.rows;
  } finally {
    client.release(); // 接続 プールに戻す
  }
}

// 簡単版
async function getUsers() {
  const result = await pool.query('SELECT * FROM users');
  return result.rows;
}
```

## 重要設定

- `max`: 同時接続数上限。DB負荷制御
- `min`: 常時保持接続数。レスポンス向上  
- `idle`: 未使用接続 自動切断時間
- `client.release()`: 必須。忘れるとリーク

プール接続 = 高負荷時安定。毎回ハンドシェイク不要。

