## より実践的な例: ファイル操作

### Before（コールバック地獄）
```javascript
const fs = require('fs');

function processFiles(callback) {
  fs.readFile('file1.txt', 'utf8', (err, data1) => {
    if (err) {
      callback(err);
      return;
    }

    fs.readFile('file2.txt', 'utf8', (err, data2) => {
      if (err) {
        callback(err);
        return;
      }

      const combinedData = data1 + data2;

      fs.writeFile('output.txt', combinedData, (err) => {
        if (err) {
          callback(err);
          return;
        }

        fs.stat('output.txt', (err, stats) => {
          if (err) {
            callback(err);
            return;
          }

          callback(null, {
            data: combinedData,
            size: stats.size
          });
        });
      });
    });
  });
}
```

### After（async/await）
```javascript
const fs = require('fs').promises;

async function processFiles() {
  try {
    const data1 = await fs.readFile('file1.txt', 'utf8');
    const data2 = await fs.readFile('file2.txt', 'utf8');

    const combinedData = data1 + data2;

    await fs.writeFile('output.txt', combinedData);
    const stats = await fs.stat('output.txt');

    return {
      data: combinedData,
      size: stats.size
    };
  } catch (error) {
    throw error;
  }
}

// 使用例
async function main() {
  try {
    const result = await processFiles();
    console.log('処理完了:', result);
  } catch (error) {
    console.error('エラー:', error.message);
  }
}
```

## 並列処理の最適化

複数の非同期処理が独立している場合は、`Promise.all`を使用して並列実行できます。

```javascript
// 逐次実行（遅い）
async function fetchDataSequentially(userId) {
  try {
    const user = await getUserInfoPromise(userId);
    const posts = await getUserPostsPromise(user.id);
    const profile = await getUserProfilePromise(user.id); // userに依存しない場合

    return { user, posts, profile };
  } catch (error) {
    throw error;
  }
}

// 並列実行（速い）
async function fetchDataInParallel(userId) {
  try {
    const user = await getUserInfoPromise(userId);

    // postsとprofileを並列で取得
    const [posts, profile] = await Promise.all([
      getUserPostsPromise(user.id),
      getUserProfilePromise(user.id)
    ]);

    return { user, posts, profile };
  } catch (error) {
    throw error;
  }
}
```

## リファクタリングのメリット

1. **可読性の向上**: ネストが浅くなり、コードが読みやすくなります
2. **エラーハンドリングの簡素化**: try-catchで統一的にエラー処理ができます
3. **デバッグの容易さ**: スタックトレースが追いやすくなります
4. **保守性の向上**: コードの修正や拡張が簡単になります

async/awaitを使用することで、コールバック地獄から解放され、より保守しやすいコードになります。

