```javascript
// Promiseベースの関数に変換
function getUserById(userId) {
    return new Promise((resolve, reject) => {
        // 非同期処理
        setTimeout(() => {
            if (userId > 0) {
                resolve({ id: userId, name: `User${userId}` });
            } else {
                reject(new Error('Invalid user ID'));
            }
        }, 100);
    });
}

function getPostsByUserId(userId) {
    return new Promise((resolve, reject) => {
        setTimeout(() => {
            resolve([
                { id: 1, userId, title: 'Post 1' },
                { id: 2, userId, title: 'Post 2' }
            ]);
        }, 100);
    });
}

function getCommentsForPosts(posts) {
    return new Promise((resolve, reject) => {
        setTimeout(() => {
            const comments = posts.map(post => ({
                postId: post.id,
                comment: `Comment for ${post.title}`
            }));
            resolve(comments);
        }, 100);
    });
}

function getLikesForPosts(posts) {
    return new Promise((resolve, reject) => {
        setTimeout(() => {
            const likes = posts.map(post => ({
                postId: post.id,
                likes: Math.floor(Math.random() * 100)
            }));
            resolve(likes);
        }, 100);
    });
}
```

### Step 2: async/awaitでリファクタリング

```javascript
