コールバック地獄の典型例とasync/awaitを使ったリファクタリングを示します。

## Before: コールバック地獄

```javascript
function fetchUserData(userId, callback) {
  getUserById(userId, (err, user) => {
    if (err) {
      callback(err, null);
      return;
    }

    getPosts(user.id, (err, posts) => {
      if (err) {
        callback(err, null);
        return;
      }

      getComments(posts[0].id, (err, comments) => {
        if (err) {
          callback(err, null);
          return;
        }

        getUserProfile(user.id, (err, profile) => {
          if (err) {
            callback(err, null);
            return;
          }

          callback(null, {
            user,
            posts,
            comments,
            profile
          });
        });
      });
    });
  });
}
```

## After: async/await

```javascript
async function fetchUserData(userId) {
  try {
    const user = await getUserById(userId);
    const posts = await getPosts(user.id);
    const comments = await getComments(posts[0].id);
    const profile = await getUserProfile(user.id);

    return {
      user,
      posts,
      comments,
      profile
    };
  } catch (error) {
    throw error;
  }
}
```

## さらに最適化（並列実行）

```javascript
async function fetchUserData(userId) {
  try {
    const user = await getUserById(userId);
    const posts = await getPosts(user.id);

    // コメントとプロフィールは並列で取得可能
    const [comments, profile] = await Promise.all([
      getComments(posts[0].id),
      getUserProfile(user.id)
    ]);

    return {
      user,
      posts,
      comments,
      profile
    };
  } catch (error) {
    throw error;
  }
}
```

## 使用例

```javascript
// 使用方法
async function main() {
  try {
    const userData = await fetchUserData(123);
    console.log(userData);
  } catch (error) {
    console.error('エラー:', error.message);
  }
}

main();
```

**メリット:**
- 可読性が大幅に向上
- エラーハンドリングが簡潔
- デバッグが容易
- 並列処理も組み合わせやすい

