ReactのError Boundaryを実装する方法をご説明します。Error Boundaryは、子コンポーネントでJavaScriptエラーが発生した際にキャッチし、フォールバックUIを表示するためのReactコンポーネントです。

## 基本的なError Boundaryの実装

### 1. クラスコンポーネント版

```jsx
import React, { Component } from 'react';

class ErrorBoundary extends Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }

  static getDerivedStateFromError(error) {
    // 次のレンダーでフォールバックUIを表示するために状態を更新
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    // エラー情報を状態に保存
    this.setState({
      error: error,
      errorInfo: errorInfo
    });

    // エラーログを送信する場合
    console.error('Error Boundary caught an error:', error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      // フォールバックUIをカスタマイズできます
      return (
        <div style={{ padding: '20px', border: '1px solid #ff0000', borderRadius: '4px' }}>
          <h2>Something went wrong.</h2>
          {this.props.showDetails && (
            <details style={{ whiteSpace: 'pre-wrap' }}>
              <summary>Error Details</summary>
              {this.state.error && this.state.error.toString()}
              <br />
              {this.state.errorInfo.componentStack}
            </details>
          )}
          <button onClick={() => window.location.reload()}>
            Reload Page
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;
```

### 2. より高機能なError Boundary

```jsx
import React, { Component } from 'react';

class AdvancedErrorBoundary extends Component {
  constructor(props) {
    super(props);
    this.state = { 
      hasError: false, 
      error: null, 
      errorInfo: null,
      eventId: null 
    };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    this.setState({
      error: error,
      errorInfo: errorInfo
    });

    // エラーレポーティングサービスに送信
    this.logErrorToService(error, errorInfo);
  }

  logErrorToService = (error, errorInfo) => {
    // 例: Sentryなどのエラー追跡サービスに送信
    console.error('Error logged:', {
      error: error.toString(),
      errorInfo: errorInfo.componentStack,
      timestamp: new Date().toISOString(),
      userAgent: navigator.userAgent,
      url: window.location.href
    });
  };

  handleRetry = () => {
    this.setState({ 
      hasError: false, 
      error: null, 
      errorInfo: null 
    });
  };

  render() {
    if (this.state.hasError) {
      const { fallback: Fallback } = this.props;

      // カスタムフォールバックコンポーネントがある場合
      if (Fallback) {
        return (
          <Fallback
            error={this.state.error}
            errorInfo={this.state.errorInfo}
            onRetry={this.handleRetry}
          />
        );
      }

      // デフォルトのフォールバックUI
      return (
        <div className="error-boundary">
          <div className="error-boundary__content">
            <h1>エラーが発生しました</h1>
            <p>申し訳ございません。予期しないエラーが発生しました。</p>

            <div className="error-boundary__actions">
              <button 
                onClick={this.handleRetry}
                className="error-boundary__retry-btn"
              >
                再試行
              </button>
              <button 
                onClick={() => window.location.reload()}
                className="error-boundary__reload-btn"
              >
                ページを再読み込み
              </button>
            </div>

            {process.env.NODE_ENV === 'development' && (
              <details className="error-boundary__details">
                <summary>開発者向け情報</summary>
                <pre>{this.state.error?.stack}</pre>
                <pre>{this.state.errorInfo?.componentStack}</pre>
              </details>
            )}
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

export default AdvancedErrorBoundary;
```

### 3. カスタムフォールバックコンポーネント

```jsx
// ErrorFallback.jsx
import React from 'react';

const ErrorFallback = ({ error, errorInfo, onRetry }) => {
  return (
    <div className="error-fallback">
      <div className="error-fallback__icon">⚠️</div>
      <h2 className="error-fallback__title">Something went wrong</h2>
      <p className="error-fallback__message">
        We're sorry, but something unexpected happened. Please try again.
      </p>

      <div className="error-fallback__actions">
        <button onClick={onRetry} className="btn btn-primary">
          Try again
        </button>
        <button 
          onClick={() => window.location.href = '/'}
          className="btn btn-secondary"
        >
          Go to Home
        </button>
      </div>

      {process.env.NODE_ENV === 'development' && (
        <details className="error-fallback__debug">
          <summary>Debug Information</summary>
          <pre className="error-fallback__stack">
            {error?.stack}
          </pre>
        </details>
      )}
    </div>
  );
};

export default ErrorFallback;
```

## 使用例

### 1. 基本的な使用方法

```jsx
import React from 'react';
import ErrorBoundary from './ErrorBoundary';
import MyComponent from './MyComponent';

function App() {
  return (
    <div className="App">
      <h1>My Application</h1>

      <ErrorBoundary>
        <MyComponent />
      </ErrorBoundary>
    </div>
  );
}

export default App;
```

### 2. カスタムフォールバックを使用

```jsx
import React from 'react';
import AdvancedErrorBoundary from './AdvancedErrorBoundary';
import ErrorFallback from './ErrorFallback';
import Dashboard from './Dashboard';

function App() {
  return (
    <div className="App">
      <AdvancedErrorBoundary fallback={ErrorFallback}>
        <Dashboard />
      </AdvancedErrorBoundary>
    </div>
  );
}
```

### 3. 複数のError Boundaryを使用

```jsx
import React from 'react';
import ErrorBoundary from './ErrorBoundary';
import Sidebar from './Sidebar';
import MainContent from './MainContent';

function App() {
  return (
    <div className="app-layout">
      {/* サイドバー用のError Boundary */}
      <ErrorBoundary>
        <Sidebar />
      </ErrorBoundary>

      {/* メインコンテンツ用のError Boundary */}
      <ErrorBoundary>
        <MainContent />
      </ErrorBoundary>
    </div>
  );
}
```

## スタイリング（CSS例）

