## 注意点

1. **Error Boundaryがキャッチできないエラー**：
   - イベントハンドラー内のエラー
   - 非同期コード（setTimeout、Promise など）
   - サーバーサイドレンダリング中のエラー
   - Error Boundary自体で発生したエラー

2. **Hook版は存在しない**：
   - Error Boundaryはクラスコンポーネントでのみ実装可能
   - `componentDidCatch`と`getDerivedStateFromError`はクラス専用

3. **本番環境での使用**：
   - 開発環境では詳細なエラー情報を表示
   - 本番環境ではユーザーフレンドリーなメッセージを表示

この実装により、アプリケーションでエラーが発生した際に適切にハンドリングし、ユーザーエクスペリエンスを向上させることができます。

ReactのError Boundaryを実装する方法を説明します。Error Boundaryは、子コンポーネントで発生したJavaScriptエラーをキャッチし、エラーをログに記録して、代替のUIを表示できる仕組みです。

## 基本的なError Boundaryの実装

### 1. クラスコンポーネントでのError Boundary

```jsx
import React from 'react';

class ErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = { hasError: false, error: null, errorInfo: null };
  }

  static getDerivedStateFromError(error) {
    // エラーが発生した際に state を更新
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    // エラーログを記録
    console.error('Error Boundary caught an error:', error, errorInfo);

    this.setState({
      error: error,
      errorInfo: errorInfo
    });

    // エラー報告サービスにログを送信することも可能
    // logErrorToService(error, errorInfo);
  }

  render() {
    if (this.state.hasError) {
      // エラー時の代替UI
      return (
        <div style={{ padding: '20px', border: '1px solid #ff6b6b', borderRadius: '4px' }}>
          <h2>🚨 何かがうまくいかなかったようです</h2>
          <p>申し訳ございませんが、エラーが発生しました。</p>

          {/* 開発環境でのみエラー詳細を表示 */}
          {process.env.NODE_ENV === 'development' && (
            <details style={{ whiteSpace: 'pre-wrap', marginTop: '10px' }}>
              <summary>エラー詳細（開発環境のみ）</summary>
              {this.state.error && this.state.error.toString()}
              <br />
              {this.state.errorInfo.componentStack}
            </details>
          )}

          <button 
            onClick={() => window.location.reload()}
            style={{ marginTop: '10px', padding: '8px 16px' }}
          >
            ページをリロード
          </button>
        </div>
      );
    }

    return this.props.children;
  }
}

export default ErrorBoundary;
```

### 2. より高機能なError Boundary

```jsx
import React from 'react';

class AdvancedErrorBoundary extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      hasError: false,
      error: null,
      errorInfo: null,
      eventId: null
    };
  }

  static getDerivedStateFromError(error) {
    return { hasError: true };
  }

  componentDidCatch(error, errorInfo) {
    const eventId = this.generateEventId();

    console.error('Error Boundary caught an error:', error, errorInfo);

    this.setState({
      error: error,
      errorInfo: errorInfo,
      eventId: eventId
    });

    // カスタムエラー処理
    if (this.props.onError) {
      this.props.onError(error, errorInfo, eventId);
    }

    // エラー報告サービスにログを送信
    this.logError(error, errorInfo, eventId);
  }

  generateEventId = () => {
    return Date.now().toString(36) + Math.random().toString(36).substr(2);
  };

  logError = async (error, errorInfo, eventId) => {
    try {
      // 実際のエラー報告サービス（Sentry、LogRocket等）に送信
      const errorReport = {
        message: error.message,
        stack: error.stack,
        componentStack: errorInfo.componentStack,
        eventId: eventId,
        userAgent: navigator.userAgent,
        timestamp: new Date().toISOString(),
        url: window.location.href
      };

      console.log('Error report:', errorReport);
      // await fetch('/api/error-report', {
      //   method: 'POST',
      //   headers: { 'Content-Type': 'application/json' },
      //   body: JSON.stringify(errorReport)
      // });
    } catch (reportingError) {
      console.error('Failed to report error:', reportingError);
    }
  };

  handleRetry = () => {
    this.setState({
      hasError: false,
      error: null,
      errorInfo: null,
      eventId: null
    });
  };

  render() {
    if (this.state.hasError) {
      // カスタムエラーUIが提供されている場合
      if (this.props.fallback) {
        return this.props.fallback(
          this.state.error,
          this.state.errorInfo,
          this.handleRetry
        );
      }

      // デフォルトのエラーUI
      return (
        <div className="error-boundary">
          <div className="error-content">
            <h1>🚨 エラーが発生しました</h1>
            <p>
              申し訳ございませんが、予期しないエラーが発生しました。
              <br />
              問題が続く場合は、サポートにお問い合わせください。
            </p>

            {this.state.eventId && (
              <p className="error-id">
                エラーID: <code>{this.state.eventId}</code>
              </p>
            )}

            <div className="error-actions">
              <button onClick={this.handleRetry} className="retry-button">
                再試行
              </button>
              <button 
                onClick={() => window.location.reload()} 
                className="reload-button"
              >
                ページをリロード
              </button>
            </div>

            {/* 開発環境でのみエラー詳細を表示 */}
            {process.env.NODE_ENV === 'development' && (
              <details className="error-details">
                <summary>エラー詳細</summary>
                <pre>{this.state.error?.toString()}</pre>
                <pre>{this.state.errorInfo?.componentStack}</pre>
              </details>
            )}
          </div>
        </div>
      );
    }

    return this.props.children;
  }
}

export default AdvancedErrorBoundary;
```

### 3. React Hooksを使用したError Boundaryラッパー

```jsx
// useErrorBoundary.js
import { useState, useCallback } from 'react';

export const useErrorBoundary = () => {
  const [error, setError] = useState(null);

  const captureError = useCallback((error) => {
    setError(error);
  }, []);

  const resetError = useCallback(() => {
    setError(null);
  }, []);

  if (error) {
    throw error;
  }

  return { captureError, resetError };
};

// ErrorBoundaryProvider.jsx
import React from 'react';
import AdvancedErrorBoundary from './AdvancedErrorBoundary';

const ErrorBoundaryProvider = ({ children, ...errorBoundaryProps }) => {
  return (
    <AdvancedErrorBoundary {...errorBoundaryProps}>
      {children}
    </AdvancedErrorBoundary>
  );
};

export default ErrorBoundaryProvider;
```

