      <h3>正常なコンポーネント</h3>
      <button onClick={() => setShouldThrow(true)}>
        エラーを発生させる
      </button>
    </div>
  );
}

// アプリケーション
function App() {
  return (
    <div>
      <h1>React Error Boundary Example</h1>

      {/* Error Boundaryで包む */}
      <ErrorBoundary
        message="このセクションでエラーが発生しました"
        showDetails={true}
        onError={(error, errorInfo) => {
          // エラー監視サービスに送信
          console.error('Error reported:', error);
        }}
      >
        <BuggyComponent />
      </ErrorBoundary>

      {/* 別のセクション */}
      <ErrorBoundary>
        <div>
          <h3>別のセクション</h3>
          <p>ここは正常に動作します</p>
        </div>
      </ErrorBoundary>
    </div>
  );
}

export default App;
```

