        proxy_pass http://api-backend/;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
    }

    # 静的ファイル
    location /static/ {
        proxy_pass http://static-backend/;
    }

    # その他すべて
    location / {
        proxy_pass http://web-backend;
    }
}

upstream api-backend {
    server 127.0.0.1:3001;
}

upstream static-backend {
    server 127.0.0.1:3002;
}

upstream web-backend {
    server 127.0.0.1:3000;
}
```

### 4. HTTPS対応のリバースプロキシ
```nginx
server {
    listen 443 ssl http2;
    server_name example.com;

    ssl_certificate /path/to/certificate.crt;
    ssl_certificate_key /path/to/private.key;

    location / {
        proxy_pass http://backend;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto https;

        # セキュリティヘッダー
        proxy_set_header X-Forwarded-SSL on;
    }
}

# HTTPからHTTPSへのリダイレクト
server {
    listen 80;
    server_name example.com;
    return 301 https://$server_name$request_uri;
}
```

## パフォーマンス最適化設定

### 5. 詳細なプロキシ設定
```nginx
server {
    listen 80;
    server_name example.com;

    location / {
        proxy_pass http://backend;

        # ヘッダー設定
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        # タイムアウト設定
        proxy_connect_timeout 30s;
        proxy_send_timeout 30s;
        proxy_read_timeout 30s;

        # バッファリング設定
        proxy_buffering on;
        proxy_buffer_size 4k;
        proxy_buffers 8 4k;
        proxy_busy_buffers_size 8k;

        # キャッシュ無効化
        proxy_no_cache 1;
        proxy_cache_bypass 1;
    }
}
```

### 6. 負荷分散アルゴリズム
```nginx
# ラウンドロビン（デフォルト）
upstream backend-round-robin {
    server 192.168.1.10:3000;
    server 192.168.1.11:3000;
    server 192.168.1.12:3000;
}

# 最小接続数
upstream backend-least-conn {
    least_conn;
    server 192.168.1.10:3000;
    server 192.168.1.11:3000;
    server 192.168.1.12:3000;
}

# IPハッシュ（セッション保持）
upstream backend-ip-hash {
    ip_hash;
    server 192.168.1.10:3000;
    server 192.168.1.11:3000;
    server 192.168.1.12:3000;
}
```

## ヘルスチェック設定

### 7. アップストリームヘルスチェック
```nginx
upstream backend {
    server 192.168.1.10:3000 max_fails=3 fail_timeout=30s;
    server 192.168.1.11:3000 max_fails=3 fail_timeout=30s;
    server 192.168.1.12:3000 max_fails=3 fail_timeout=30s;
}
```

## WebSocket対応

### 8. WebSocketプロキシ設定
```nginx
upstream websocket-backend {
    server 127.0.0.1:3000;
}

server {
    listen 80;
    server_name example.com;

    location /websocket {
        proxy_pass http://websocket-backend;
        proxy_http_version 1.1;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection "upgrade";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;

        # WebSocket用の長時間接続
        proxy_read_timeout 86400;
    }
}
```

## キャッシュ設定

### 9. プロキシキャッシュ
```nginx
# キャッシュパス設定（http ブロック内）
proxy_cache_path /var/cache/nginx levels=1:2 keys_zone=my_cache:10m max_size=10g 
                 inactive=60m use_temp_path=off;

server {
    listen 80;
    server_name example.com;

    location / {
        proxy_pass http://backend;
        proxy_cache my_cache;
        proxy_cache_valid 200 302 10m;
        proxy_cache_valid 404 1m;
        proxy_cache_use_stale error timeout invalid_header updating;

        # キャッシュヘッダー追加
        add_header X-Cache-Status $upstream_cache_status;
    }
}
```

## 設定のテスト

### 10. 設定確認コマンド
```bash
# 設定ファイルの文法チェック
sudo nginx -t

# 設定の詳細確認
sudo nginx -T

# 設定リロード
sudo nginx -s reload

# Nginxの再起動
sudo systemctl restart nginx
```

これらの設定を参考に、あなたの環境に合わせてカスタマイズしてください。特定の用途や要件があれば、より詳細な設定についてお聞かせください。

