```typescript
// API例
interface ApiResponse<T> {
  data: T;
  status: number;
}

const userResponse: ApiResponse<User> = {
  data: { id: 1, name: "太郎" },
  status: 200
};
```

制約付き:
```typescript
function getLength<T extends { length: number }>(item: T): number {
  return item.length;  // T に length プロパティ必須
}
```

型推論 自動:
```typescript
const result = getArray([1, 2, 3]);  // T = number 自動推論
```

ジェネリクス = 型の変数。

関数で値を受け取るように、型も受け取れる。

```typescript
// 普通の関数
function echo(value: string): string {
  return value;
}

// ジェネリック関数
function echo<T>(value: T): T {
  return value;
}
```

`<T>` = 型パラメータ。使用時に具体的な型を指定。

```typescript
const str = echo<string>("hello");    // T = string
const num = echo<number>(42);         // T = number
const bool = echo<boolean>(true);     // T = boolean
```

型推論で `<>` 省略可:

```typescript
const str = echo("hello");    // 自動でstring型
const num = echo(42);         // 自動でnumber型
```

配列例:

```typescript
function getFirst<T>(arr: T[]): T {
  return arr[0];
}

const first = getFirst([1, 2, 3]);        // number
const firstStr = getFirst(["a", "b"]);    // string
```

制約つけることも可:

```typescript
function getLength<T extends { length: number }>(item: T): number {
  return item.length;
}

getLength("hello");     // OK: string has length
getLength([1, 2, 3]);   // OK: array has length
getLength(123);         // エラー: number no length
```

複数型パラメータ:

```typescript
function pair<T, U>(first: T, second: U): [T, U] {
  return [first, second];
}

const result = pair("hello", 42);  // [string, number]
```

要点: 同じロジック、異なる型で再利用。型安全性維持。

## ジェネリクス = 型の変数

関数に値渡すように、型も渡せる仕組み。

```typescript
// 普通の関数
function echo(value: string): string {
  return value;
}

// ジェネリック関数
function echo<T>(value: T): T {
  return value;
}
```

`<T>` = 型の変数。使う時に決まる。

```typescript
const str = echo<string>("hello");     // T = string
const num = echo<number>(42);          // T = number
const bool = echo<boolean>(true);      // T = boolean

// 型推論で省略可
const str2 = echo("hello");  // 自動でT = string
```

## 配列例

```typescript
function getFirst<T>(arr: T[]): T {
  return arr[0];
}

const firstStr = getFirst(["a", "b"]);    // string
const firstNum = getFirst([1, 2, 3]);     // number
```

## インターフェース

```typescript
interface Box<T> {
  value: T;
}

const strBox: Box<string> = { value: "hello" };
const numBox: Box<number> = { value: 42 };
```

## 制約

```typescript
interface HasLength {
  length: number;
}

function logLength<T extends HasLength>(item: T): T {
  console.log(item.length);  // OK
  return item;
}

logLength("hello");     // OK
logLength([1, 2, 3]);   // OK
logLength(42);          // エラー
```

同じ関数で複数の型対応。型安全性維持。

normal_texts:
Node.jsアプリのメモリリークを調査する方法をご説明します。

## 1. 基本的な監視とツール

### メモリ使用量の監視
```javascript
// プロセスのメモリ使用量を確認
console.log(process.memoryUsage());
// 出力例:
// {
//   rss: 4935680,        // 物理メモリ使用量
//   heapTotal: 1826816,  // V8ヒープの総容量
//   heapUsed: 650472,    // V8ヒープの使用量
//   external: 49879,     // C++オブジェクトのメモリ使用量
//   arrayBuffers: 9386   // ArrayBufferのメモリ使用量
// }

// 定期的な監視
setInterval(() => {
  const usage = process.memoryUsage();
  console.log(`Memory: ${Math.round(usage.heapUsed / 1024 / 1024 * 100) / 100} MB`);
}, 1000);
```

### Node.jsビルトインのプロファイラー
```bash
# --inspectフラグでデバッグ機能を有効化
node --inspect app.js

# またはプロダクション用
node --inspect=0.0.0.0:9229 app.js
```

## 2. 専門的なツール

### 1) clinic.js
```bash
npm install -g clinic
clinic doctor -- node app.js
clinic bubbleprof -- node app.js
clinic heapprofiler -- node app.js
```

### 2) 0x (フレームグラフ生成)
```bash
npm install -g 0x
0x node app.js
```

### 3) heapdump
```bash
npm install heapdump
```

```javascript
const heapdump = require('heapdump');

// ヒープダンプを作成
heapdump.writeSnapshot('/tmp/' + Date.now() + '.heapsnapshot');

// シグナルでヒープダンプを作成
process.on('SIGUSR2', () => {
  heapdump.writeSnapshot('/tmp/' + Date.now() + '.heapsnapshot');
});
```

## 3. Chrome DevToolsでの解析

### ヒープスナップショットの取得
```javascript
// Chrome DevToolsに接続するためのコード
const inspector = require('inspector');
const fs = require('fs');

const session = new inspector.Session();
session.connect();

function takeHeapSnapshot() {
  return new Promise((resolve) => {
    const chunks = [];
    session.on('HeapProfiler.addHeapSnapshotChunk', (m) => {
      chunks.push(m.params.chunk);
    });

    session.post('HeapProfiler.takeHeapSnapshot', null, () => {
      const snapshot = chunks.join('');
      fs.writeFileSync(`./heap-${Date.now()}.heapsnapshot`, snapshot);
      resolve();
    });
  });
}
```

## 4. 一般的なメモリリークパターンの特定

### グローバル変数の確認
```javascript
// 悪い例：グローバル変数にデータを蓄積
let globalCache = [];

function addToCache(data) {
  globalCache.push(data); // これがメモリリークの原因
}

// 良い例：適切なクリーンアップ
class DataManager {
  constructor() {
    this.cache = new Map();
  }

  addData(key, data) {
    this.cache.set(key, data);
  }

  cleanup() {
    this.cache.clear();
  }
}
```

### イベントリスナーのリーク
```javascript
// 悪い例：リスナーが削除されない
function createHandler() {
  const handler = (data) => {
    // 処理
  };

  emitter.on('data', handler);
  // handlerが削除されない
}

// 良い例：適切なクリーンアップ
function createHandler() {
  const handler = (data) => {
    // 処理
  };

  emitter.on('data', handler);

  // クリーンアップ関数を返す
  return () => {
    emitter.removeListener('data', handler);
  };
}
```

### タイマーのリーク
```javascript
// 悪い例：タイマーがクリアされない
function startTimer() {
  setInterval(() => {
    // 処理
  }, 1000);
}

// 良い例：タイマーを管理
class TimerManager {
  constructor() {
    this.timers = [];
  }

  startTimer(callback, interval) {
    const timer = setInterval(callback, interval);
    this.timers.push(timer);
    return timer;
  }

  clearAll() {
    this.timers.forEach(clearInterval);
    this.timers = [];
  }
}
```

## 5. 実際の調査手順

### ステップ1: ベースライン確立
```javascript
// アプリケーション起動時のメモリ使用量を記録
const startMemory = process.memoryUsage();
console.log('Start memory:', startMemory);

// 定期的な監視を設定
const memoryLog = [];
setInterval(() => {
  const current = process.memoryUsage();
  memoryLog.push({
    timestamp: Date.now(),
    heapUsed: current.heapUsed,
    rss: current.rss
  });
}, 5000);
```

### ステップ2: 負荷テスト
```javascript
// 人工的な負荷をかけてメモリリークを検出
async function loadTest() {
  const iterations = 1000;

  for (let i = 0; i < iterations; i++) {
    // アプリケーションの主要な処理を実行
    await performMainOperation();

    if (i % 100 === 0) {
      // ガベージコレクションを強制実行
      if (global.gc) {
        global.gc();
      }

      const memory = process.memoryUsage();
      console.log(`Iteration ${i}: ${memory.heapUsed / 1024 / 1024} MB`);
    }
  }
}

// ガベージコレクションを有効にしてアプリを起動
// node --expose-gc app.js
```

### ステップ3: 分析とレポート
```javascript
function analyzeMemoryTrend(memoryLog) {
  const trend = memoryLog.map((entry, index) => ({
    ...entry,
    growth: index > 0 ? entry.heapUsed - memoryLog[0].heapUsed : 0
  }));

  const avgGrowth = trend.reduce((sum, entry) => sum + entry.growth, 0) / trend.length;

  console.log('Memory analysis:', {
    totalGrowth: trend[trend.length - 1].growth,
    averageGrowth: avgGrowth,
    isLeaking: avgGrowth > 1024 * 1024 // 1MB以上の成長をリークと判定
  });

  return trend;
}
```

## 6. 予防策

### WeakMapとWeakSetの使用
```javascript
// 通常のMapは強参照
const cache = new Map();

// WeakMapは弱参照（オブジェクトがGCされると自動的に削除）
const weakCache = new WeakMap();

function cacheUserData(user, data) {
  weakCache.set(user, data); // userオブジェクトがGCされると自動削除
}
```

### リソース管理の自動化
```javascript
class ResourceManager {
  constructor() {
    this.resources = new Set();

    // プロセス終了時の自動クリーンアップ
    process.on('SIGINT', () => this.cleanup());
    process.on('SIGTERM', () => this.cleanup());
  }

  register(resource) {
    this.resources.add(resource);
  }

  cleanup() {
    for (const resource of this.resources) {
      if (typeof resource.destroy === 'function') {
        resource.destroy();
      }
    }
    this.resources.clear();
  }
}
```

これらの方法を組み合わせて、メモリリークの原因を特定し、対策を講じることができます。特に本番環境では、定期的な監視とアラートの設定が重要です。

Node.jsアプリのメモリリークを調査する方法について、段階的に説明いたします。

## 1. 基本的な監視とデバッグ

### メモリ使用量の監視
```javascript
// メモリ使用量を定期的に出力
setInterval(() => {
  const memoryUsage = process.memoryUsage();
  console.log({
    rss: Math.round(memoryUsage.rss / 1024 / 1024) + 'MB', // 物理メモリ
    heapUsed: Math.round(memoryUsage.heapUsed / 1024 / 1024) + 'MB', // 使用中のヒープ
    heapTotal: Math.round(memoryUsage.heapTotal / 1024 / 1024) + 'MB', // 総ヒープ
    external: Math.round(memoryUsage.external / 1024 / 1024) + 'MB' // 外部メモリ
  });
}, 1000);
```

## 2. Node.js内蔵のプロファイリングツール

### --inspect フラグでデバッグ
```bash
# デバッグモードで起動
node --inspect app.js

# 特定のポートでデバッグ
node --inspect=9229 app.js
```

Chrome DevToolsの `chrome://inspect` にアクセスして、メモリタブでヒープスナップショットを取得できます。

## 3. 専用ツールを使った調査

### clinic.js
```bash
# インストール
npm install -g clinic

# メモリ使用量の詳細分析
clinic doctor -- node app.js

# ヒーププロファイリング
clinic heapprofiler -- node app.js
```

### 0x（フレームグラフ）
```bash
npm install -g 0x
0x app.js
```

## 4. ヒープダンプの取得と分析

### heapdumpパッケージ
```javascript
const heapdump = require('heapdump');

// 手動でヒープダンプを作成
heapdump.writeSnapshot('/tmp/' + Date.now() + '.heapsnapshot');

// SIGUSR2シグナルで自動作成
process.on('SIGUSR2', () => {
  heapdump.writeSnapshot('/tmp/' + Date.now() + '.heapsnapshot');
});
```

## 5. よくあるメモリリークのパターンと対策

### グローバル変数の蓄積
```javascript
// 問題のあるコード
let cache = {};
function addToCache(key, value) {
  cache[key] = value; // 無制限に蓄積される
}

// 改善版
const LRU = require('lru-cache');
const cache = new LRU({ max: 1000, maxAge: 1000 * 60 * 60 });
```

### イベントリスナーの削除忘れ
```javascript
// 問題のあるコード
function setupListener() {
  process.on('message', handler);
  // removeListenerを忘れがち
}

// 改善版
function setupListener() {
  const cleanup = () => {
    process.removeListener('message', handler);
  };

  process.on('message', handler);
  return cleanup;
}
```

### タイマーの削除忘れ
```javascript
// 問題のあるコード
const interval = setInterval(() => {
  // 処理
}, 1000);
// clearIntervalを忘れがち

// 改善版
const interval = setInterval(() => {
  // 処理
}, 1000);

process.on('SIGINT', () => {
  clearInterval(interval);
  process.exit();
});
```

## 6. 自動メモリリーク検出

### memwatch-next
```javascript
const memwatch = require('memwatch-next');

memwatch.on('leak', (info) => {
  console.error('Memory leak detected:', info);
});

memwatch.on('stats', (stats) => {
  console.log('GC stats:', stats);
});
```

## 7. 本番環境での監視

### PM2でのメモリ監視
```javascript
// ecosystem.config.js
module.exports = {
  apps: [{
    name: 'myapp',
    script: 'app.js',
    max_memory_restart: '1G', // メモリ使用量が1GBを超えたら再起動
    monitoring: false
  }]
};
```

## 8. 調査のベストプラクティス

1. **段階的アプローチ**: 基本的な監視から始めて、必要に応じて詳細な分析を行う
2. **本番環境での影響を最小化**: デバッグツールは性能に影響するため、本番では慎重に使用
3. **定期的な監視**: メモリ使用量のトレンドを把握する
4. **コードレビュー**: リーク源となりやすいパターンを事前にチェック

これらの方法を組み合わせることで、効果的にメモリリークを特定し、解決できます。

Node.jsアプリのメモリリークを調査する方法について、体系的に説明いたします。

## 1. 基本的な調査手順

### まずはメモリ使用量の監視
```javascript
// メモリ使用量を定期的に出力
setInterval(() => {
  const memUsage = process.memoryUsage();
  console.log({
    rss: Math.round(memUsage.rss / 1024 / 1024) + 'MB',
    heapTotal: Math.round(memUsage.heapTotal / 1024 / 1024) + 'MB',
    heapUsed: Math.round(memUsage.heapUsed / 1024 / 1024) + 'MB',
    external: Math.round(memUsage.external / 1024 / 1024) + 'MB'
  });
}, 5000);
```

## 2. Node.js組み込みツールの活用

### --inspect フラグでデバッガー接続
```bash
node --inspect=0.0.0.0:9229 app.js
```

### Chrome DevToolsでの調査
1. Chrome を開き `chrome://inspect` にアクセス
2. アプリケーションに接続
3. Memory タブでヒープスナップショットを取得

### ヒープダンプの取得
```javascript
// プログラムから手動でヒープダンプを取得
const v8 = require('v8');
const fs = require('fs');

function takeHeapSnapshot() {
  const snapshotStream = v8.getHeapSnapshot();
  const fileName = `heap-${Date.now()}.heapsnapshot`;
  const fileStream = fs.createWriteStream(fileName);
  snapshotStream.pipe(fileStream);
  console.log(`Heap snapshot saved to ${fileName}`);
}

// USR2シグナルでヒープダンプを取得
process.on('SIGUSR2', takeHeapSnapshot);
```

## 3. 専用パッケージの活用

### memwatch-next
```bash
npm install memwatch-next
```

```javascript
const memwatch = require('memwatch-next');

// メモリリークの検出
memwatch.on('leak', (info) => {
  console.error('Memory leak detected:', info);
});

// ガベージコレクション統計
memwatch.on('stats', (stats) => {
  console.log('GC stats:', stats);
});
```

### clinic.js（パフォーマンス診断）
```bash
npm install -g clinic
clinic doctor -- node app.js
```

### node-heapdump
```bash
npm install heapdump
```

```javascript
const heapdump = require('heapdump');

// 条件付きでヒープダンプを取得
if (process.memoryUsage().heapUsed > 100 * 1024 * 1024) { // 100MB以上
  heapdump.writeSnapshot((err, filename) => {
    console.log('Heap dump written to', filename);
  });
}
```

## 4. よくあるメモリリークのパターンと対処法

### グローバル変数の蓄積
```javascript
// 問題のあるコード
let cache = {};
function addToCache(key, value) {
  cache[key] = value; // 無制限に蓄積
}

// 改善例
const LRU = require('lru-cache');
const cache = new LRU({ max: 500, ttl: 1000 * 60 * 5 }); // 最大500個、5分TTL
```

### イベントリスナーの削除忘れ
```javascript
// 問題のあるコード
function setupListener() {
  process.on('message', handleMessage);
  // removeListenerを呼んでいない
}

// 改善例
function setupListener() {
  const handler = (message) => handleMessage(message);
  process.on('message', handler);

  return () => {
    process.removeListener('message', handler);
  };
}
```

### クロージャによる参照の保持
```javascript
// 問題のあるコード
function createHandler(largeData) {
  return function(req, res) {
    // largeDataを使用していないが、クロージャで参照が保持される
    res.send('Hello');
  };
}

// 改善例
function createHandler() {
  return function(req, res) {
    res.send('Hello');
  };
  // 必要なデータのみを渡す
}
```

## 5. 監視とアラート

### PM2での監視
```javascript
// ecosystem.config.js
module.exports = {
  apps: [{
    name: 'app',
    script: './app.js',
    max_memory_restart: '300M', // メモリ使用量が300MBに達したら再起動
    monitoring: false
  }]
};
```

### カスタムメモリ監視
```javascript
function monitorMemory() {
  const memUsage = process.memoryUsage();
  const heapUsedMB = memUsage.heapUsed / 1024 / 1024;

  if (heapUsedMB > 200) { // 200MB閾値
    console.warn(`High memory usage: ${heapUsedMB.toFixed(2)}MB`);

    if (heapUsedMB > 300) { // 300MBで緊急処理
      console.error('Critical memory usage, forcing GC');
      global.gc && global.gc();
    }
  }
}

setInterval(monitorMemory, 30000); // 30秒ごとにチェック
```

## 6. プロダクション環境での調査

### ログベースの監視
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'memory.log' })
  ]
});

setInterval(() => {
  const memUsage = process.memoryUsage();
  logger.info('memory_usage', {
    timestamp: new Date().toISOString(),
    pid: process.pid,
    heapUsed: memUsage.heapUsed,
    heapTotal: memUsage.heapTotal,
    rss: memUsage.rss
  });
}, 60000);
```

メモリリークの調査は継続的なプロセスです。定期的な監視と、問題が発生した際の迅速な対応が重要です。何かご不明な点がございましたら、お気軽にお尋ねください。

