**レート制限**実装法3つ:

## 1. Token Bucket
```javascript
class TokenBucket {
  constructor(capacity, refillRate) {
    this.capacity = capacity;
    this.tokens = capacity;
    this.refillRate = refillRate; // tokens/秒
    this.lastRefill = Date.now();
  }

  consume() {
    this.refill();
    if (this.tokens > 0) {
      this.tokens--;
      return true;
    }
    return false;
  }

  refill() {
    const now = Date.now();
    const tokensToAdd = Math.floor((now - this.lastRefill) / 1000 * this.refillRate);
    this.tokens = Math.min(this.capacity, this.tokens + tokensToAdd);
    this.lastRefill = now;
  }
}
```

## 2. Sliding Window (Redis)
```javascript
async function checkRateLimit(userId, limit, windowMs) {
  const now = Date.now();
  const window = Math.floor(now / windowMs);
  const key = `rate_limit:${userId}:${window}`;

  const count = await redis.incr(key);
  if (count === 1) {
    await redis.expire(key, Math.ceil(windowMs / 1000));
  }

  return count <= limit;
}
```

